/** 存紀錄表原檔，回傳「紀錄檔」列（尚未寫入）。
 *  args.file = {name,mimeType,base64}：新上傳；args.stagedId：批次匯入暫存區的檔案（改名並移到紀錄表資料夾） */
function saveRecFile_(c, args, user, now) {
  if (args.stagedId) {
    const st = findRows_('紀錄匯入', '檔案ID', String(args.stagedId))[0];
    if (!st) throw new Error('暫存區找不到檔案');
    if (st.狀態 === '已匯入') throw new Error('此檔已匯入（' + st.案件編號 + '）');
    const std = recFileName_(c, st.原檔名);
    driveFetch_('https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(st.檔案ID) + '?fields=id&addParents=' + encodeURIComponent(djFolder_()) + '&removeParents=' + encodeURIComponent(stageFolder_()),
      { method: 'patch', contentType: 'application/json', payload: JSON.stringify({ name: std }) });
    st.狀態 = '已匯入'; st.案件編號 = c.案件編號; st.說明 = std; writeRow_('紀錄匯入', st);
    return { 案件編號: c.案件編號, 檔名: std, 類型: String(st.類型 || ''), 檔案ID: st.檔案ID, 大小: st.大小, 上傳者: user.Email, 上傳時間: now };
  }
  if (args.file && args.file.base64) {
    const f = args.file, name = String(f.name || '紀錄表').replace(/[\\/:*?"<>|]/g, '_');
    if (f.base64.length > 27000000) throw new Error('檔案太大（上限約 20MB）');
    const std = recFileName_(c, name);   // 統一檔名（原檔名只用來取副檔名）
    const created = driveCreate_({ name: std, parents: [djFolder_()] }, f.base64, f.mimeType || 'application/octet-stream');
    return { 案件編號: c.案件編號, 檔名: std, 類型: String(f.mimeType || ''), 檔案ID: created.id, 大小: Math.round(f.base64.length * 3 / 4), 上傳者: user.Email, 上傳時間: now };
  }
  return null;
}

/* ---------------- 批次匯入暫存區 ----------------
 * 從其他來源（如同事的雲端資料夾）收集的紀錄表先放暫存區（擁有者雲端硬碟「督導紀錄匯入暫存」），
 * 再於督導紀錄頁「批次匯入」解析、對應案件後正式掛到案件上。
 */
function stageFolder_() {
  let folder = prop_('STAGE_FOLDER_ID');
  if (!folder) {
    const r = driveFetch_('https://www.googleapis.com/drive/v3/files?fields=id', {
      method: 'post', contentType: 'application/json',
      payload: JSON.stringify({ name: '督導紀錄匯入暫存', mimeType: 'application/vnd.google-apps.folder' })
    });
    folder = JSON.parse(r.getContentText()).id;
    setProp_('STAGE_FOLDER_ID', folder);
  }
  return folder;
}
/** 放入暫存區：args = {name, mimeType, base64, src}；同檔名同大小已在暫存區就略過 */
function apiRecStage(args, user) {
  const name = String(args.name || '').replace(/[\\/:*?"<>|]/g, '_').trim();
  if (!name || !args.base64) throw new Error('缺檔名或內容');
  if (args.base64.length > 27000000) throw new Error('檔案太大（上限約 20MB）');
  const size = Math.round(args.base64.length * 3 / 4);
  const dup = readTable_('紀錄匯入').find(r => r.原檔名 === name && Math.abs((+r.大小 || 0) - size) < 4);
  if (dup) return { skipped: true, 檔案ID: String(dup.檔案ID), 狀態: String(dup.狀態) };
  const created = driveCreate_({ name: name, parents: [stageFolder_()] }, args.base64, args.mimeType || 'application/octet-stream');
  appendRows_('紀錄匯入', [{ 檔案ID: created.id, 原檔名: name, 類型: String(args.mimeType || ''), 大小: size, 來源: String(args.src || '').slice(0, 200), 匯入者: user.Email, 匯入時間: nowStr_(), 狀態: '待對應', 案件編號: '', 說明: '' }]);
  return { ok: true, 檔案ID: created.id };
}
/** 暫存區清單（預設只列未匯入） */
function apiRecStageList(args) {
  return readTable_('紀錄匯入').filter(r => args.all || r.狀態 !== '已匯入')
    .map(r => ({ 檔案ID: String(r.檔案ID), 原檔名: String(r.原檔名), 類型: String(r.類型 || ''), 大小: r.大小, 來源: String(r.來源 || ''), 狀態: String(r.狀態 || ''), 案件編號: String(r.案件編號 || ''), 說明: String(r.說明 || '') }));
}
/** 讀暫存檔內容（base64，供前台解析） */
function apiRecStageGet(args) {
  const st = findRows_('紀錄匯入', '檔案ID', String(args.fileId || ''))[0];
  if (!st) throw new Error('暫存區找不到檔案');
  const res = driveFetch_('https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(st.檔案ID) + '?alt=media');
  return { name: String(st.原檔名), mimeType: String(st.類型 || ''), base64: Utilities.base64Encode(res.getBlob().getBytes()) };
}
/** 暫存檔標記（略過等），不刪檔 */
function apiRecStageMark(args, user) {
  const st = findRows_('紀錄匯入', '檔案ID', String(args.fileId || ''))[0];
  if (!st) throw new Error('暫存區找不到檔案');
  if (st.狀態 === '已匯入') throw new Error('已匯入的檔案不可變更');
  st.狀態 = String(args.status || '待對應'); st.說明 = String(args.note || '').slice(0, 300); writeRow_('紀錄匯入', st);
  return { ok: true };
}
